@app.get("/")
def index():
    return render_template_string(PAGE, school_logo=SCHOOL_LOGO, class_logo=CLASS_LOGO)

@app.post("/absen")
def submit_absensi():
    nama = " ".join(request.form.get("nama", "").split())[:100]
    status = request.form.get("status", "").strip()
    alasan = " ".join(request.form.get("alasan", "").split())[:500]
    allowed = {"Hadir", "Sakit", "Izin", "Dispensasi", "Alfa"}
    if not nama or status not in allowed:
        flash("Data belum lengkap. Periksa nama dan status absensi.")
        return redirect(url_for("index"))
    if status in {"Sakit", "Izin", "Dispensasi", "Alfa"} and not alasan:
        flash("Silakan isi alasan/keterangan untuk status yang dipilih.")
        return redirect(url_for("index"))

    now = datetime.now()
    tanggal = now.strftime("%d-%m-%Y")
    waktu = now.strftime("%H:%M")
    with connect_db() as con:
        con.execute(
            "INSERT INTO absensi(nama, kelas, status, alasan, tanggal, waktu) VALUES (?, ?, ?, ?, ?, ?)",
            (nama, "X TKJ 1", status, alasan, tanggal, waktu)
        )
    print("\n========== ABSENSI MASUK ==========", flush=True)
    print(f"Nama: {nama}\nKelas: X TKJ 1\nStatus: {status}\nAlasan: {alasan or '-'}\nTanggal: {tanggal}\nWaktu: {waktu}", flush=True)
    flash("Absensi berhasil dikirim. Terima kasih!")
    return redirect(url_for("index"))

@app.get("/health")
def health():
    return {"status": "ok"}, 200

if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    print(f"Server berjalan pada port {port}")
    app.run(host="0.0.0.0", port=port, debug=False)
